import { parseFootballQuestion } from './football-query.mjs';

const config=window.OM_CHAT_CONFIG||{};
const form=document.querySelector('#football-search');
const input=document.querySelector('#football-question');
const output=document.querySelector('#football-output');
const endpoint=config.footballEndpoint;
let lastController=null;

function node(tag,className,text){const el=document.createElement(tag);if(className)el.className=className;if(text!==undefined)el.textContent=text;return el;}
function thaiTime(value){return new Intl.DateTimeFormat('th-TH',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Bangkok'}).format(new Date(value));}
function errorMessage(error){return error?.message||'ค้นหาข้อมูลฟุตบอลไม่สำเร็จ กรุณาลองใหม่ครับ';}
function requestFor(question){const parsed=parseFootballQuestion(question);if(!parsed.sport)throw new Error('ลองใส่ชื่อทีม หรือคำว่า บอลวันนี้ ผลบอลเมื่อวาน และคู่ยังไม่เริ่มครับ');if(!parsed.valid)throw new Error('วันที่ไม่ถูกต้อง กรุณาใช้รูปแบบ YYYY-MM-DD ครับ');const p=new URLSearchParams({date:parsed.date,page:'1'});if(parsed.teams.length)p.set('teams',JSON.stringify(parsed.teams));if(parsed.live)p.set('live','1');if(parsed.finished)p.set('finished','1');if(parsed.upcoming)p.set('upcoming','1');if(parsed.scheduled)p.set('scheduled','1');return p;}
async function fetchData(params){if(!endpoint)throw new Error('ยังไม่ได้ตั้งค่า Backend ฟุตบอลครับ');lastController?.abort();const controller=new AbortController();lastController=controller;const timer=setTimeout(()=>controller.abort(),14000);try{const url=new URL(endpoint);params.forEach((v,k)=>url.searchParams.set(k,v));const response=await fetch(url,{credentials:'omit',referrerPolicy:'no-referrer',signal:controller.signal});let data;try{data=await response.json();}catch{throw new Error('อ่านคำตอบจากระบบฟุตบอลไม่สำเร็จครับ');}if(!response.ok)throw new Error(data?.error?.message||'ระบบฟุตบอลขัดข้องชั่วคราวครับ');return data;}catch(error){if(error.name==='AbortError')throw new Error('ระบบใช้เวลานานเกินไป กรุณาลองใหม่ครับ');throw error;}finally{clearTimeout(timer);if(lastController===controller)lastController=null;}}
function matchCard(fixture){const card=node('article','match-card');const meta=node('div','match-meta');meta.append(node('span','',`${fixture.league.country} · ${fixture.league.name}`),node('span','match-status',fixture.finished?'จบแล้ว':fixture.status==='NS'?'ยังไม่เริ่ม':fixture.status));const teams=node('div','match-teams');teams.append(node('div','match-team',fixture.home.name),node('strong','match-score',fixture.status==='NS'?'VS':`${fixture.goals.home??'–'} : ${fixture.goals.away??'–'}`),node('div','match-team',fixture.away.name));card.append(meta,teams,node('div','match-time',`${thaiTime(fixture.date)} · เวลาไทย`));const actions=node('div','match-actions');const lineup=node('button','','ดูไลน์อัป');lineup.type='button';lineup.addEventListener('click',()=>loadDetail('lineup',fixture.id));actions.append(lineup);if(fixture.status==='NS'){const predict=node('button','','คาดการณ์ %');predict.type='button';predict.addEventListener('click',()=>loadDetail('prediction',fixture.id));actions.append(predict);}card.append(actions);return card;}
function renderFixtures(data){output.replaceChildren();output.append(node('p','football-page-summary',`${data.live?'กำลังแข่ง':data.finished?'คู่จบแล้ว':data.scheduled?'คู่ยังไม่เริ่ม':'โปรแกรมและผล'} · พบ ${data.total} คู่`));if(data.scheduleNote)output.append(node('p','football-source',data.scheduleNote));if(!data.fixtures.length)output.append(node('div','football-message','ไม่พบคู่ที่ตรงกับคำค้นในช่วงข้อมูลที่แพ็กเกจรองรับครับ'));data.fixtures.forEach(f=>output.append(matchCard(f)));output.append(node('p','football-source',`${data.source} · อัปเดต ${thaiTime(data.fetchedAt)} · ข้อมูลอาจล่าช้าตามผู้ให้บริการ`));}
function renderDetail(data){output.replaceChildren();output.append(matchCard(data.fixture));if(data.kind==='prediction'){if(!data.available){output.append(node('div','football-message',data.reason));return;}const grid=node('div','football-probabilities');grid.append(node('span','',`${data.fixture.home.name} ชนะ ${data.percentages.home}%`),node('span','',`เสมอ ${data.percentages.draw}%`),node('span','',`${data.fixture.away.name} ชนะ ${data.percentages.away}%`));output.append(grid,node('p','football-source',data.note));return;}const title=node('h2','',data.status==='ready'?'ไลน์อัปครบแล้ว':data.status==='partial'?'ไลน์อัปบางส่วน':'ยังไม่มีไลน์อัป');output.append(title);const grid=node('div','lineup-grid');data.lineups.forEach(team=>{const section=node('section','lineup-team');section.append(node('h3','',team.team.name),node('p','football-source',team.available?`แผน ${team.formation||'–'} · โค้ช ${team.coach||'–'}`:'ยังไม่มีรายชื่อจากผู้ให้บริการ'));if(team.starters.length){const list=node('ol');team.starters.forEach(player=>list.append(node('li','',player.name)));section.append(list);}grid.append(section);});output.append(grid,node('p','football-source',data.note));}
async function search(question){output.setAttribute('aria-busy','true');output.replaceChildren(node('div','football-loading','กำลังค้นหาข้อมูลฟุตบอล…'));try{const data=await fetchData(requestFor(question));renderFixtures(data);}catch(error){output.replaceChildren(node('div','football-message',errorMessage(error)));}finally{output.setAttribute('aria-busy','false');}}
async function loadDetail(mode,id){output.setAttribute('aria-busy','true');output.prepend(node('div','football-loading','กำลังดึงข้อมูลเพิ่มเติม…'));try{const data=await fetchData(new URLSearchParams({mode,fixture:String(id)}));renderDetail(data);}catch(error){output.replaceChildren(node('div','football-message',errorMessage(error)));}finally{output.setAttribute('aria-busy','false');}}
form?.addEventListener('submit',event=>{event.preventDefault();search(input.value.trim());});
document.querySelectorAll('[data-query]').forEach(button=>button.addEventListener('click',()=>{input.value=button.dataset.query;search(input.value);}));
